template:
use std::sync::atomic::{AtomicBool, AtomicI32, Ordering};

fn publish(data: &AtomicI32, ready: &AtomicBool, val: i32) {
    data.store(val, Ordering::Relaxed);
    ready.store(true, Ordering::⟦slot1⟧);
}

fn consume(data: &AtomicI32, ready: &AtomicBool) -> Option<i32> {
    if ready.load(Ordering::⟦slot2⟧) {
        Some(data.load(Ordering::Relaxed))
    } else {
        None
    }
}

tests:
#[test]
fn test_publish_consume() {
    let data = AtomicI32::new(0);
    let ready = AtomicBool::new(false);
    publish(&data, &ready, 42);
    assert_eq!(consume(&data, &ready), Some(42));
}
